    if(rootCalled)std::cerr<<" rootResult="<<static_cast<int>(rootResult);else std::cerr<<" rootResult=not-called";
    std::cerr<<" scopeObservation=blocking-post-result-current generation="<<observed.generation<<" epoch="<<observed.epoch<<" revision="<<observed.revision<<" activationCommitted="<<observed.activationCommitted<<" stopping="<<observed.stopping<<" drained="<<observed.drained<<" running="<<observed.running<<" retainedOperations="<<observed.retainedOperations;
    std::cerr<<" postResultVmRunning="<<vmRunning<<" postResultDomainRevision="<<domainRevision<<std::endl;
    Check(issuedOwner!=0&&rootResult==ScopeResult::Ok,"actual typed root decision");result.facts=Facts(fixture,result.endpoint);return result;
