    const auto freshResult=Decisions::FreshDecision(scope,root,fresh);Check(freshResult==ScopeResult::Ok,"uncommitted lifecycle fresh ownership accepted");
    const auto after=scope->Current();const auto held=Scope::Observe(*scope);Check(!after.activationCommitted&&after.generation==before.generation&&after.epoch==before.epoch&&after.revision==before.revision&&domain->Revision()==revision,"lifecycle ownership changes no activation epoch or marker");
    Check(held.rootReservations==1&&held.commandTickets==1&&held.nonCommandFreshReservations==0&&fresh.Context().owner==root.owner&&fresh.Context().reservation!=root.reservation,"candidate lifecycle uses same root plus one exact native ticket");
