    fresh={};Check(Scope::Observe(*scope).commandTickets==0&&Scope::Observe(*scope).rootReservations==1,"candidate lifecycle releases exact ticket only");
    {auto q=RuntimeScopeTestAccess::ReserveState(*scope);Check(q.owns_lock(),"actual candidate Q held");auto work=std::async(std::launch::async,[&]{LifecycleDecision deniedRoot,deniedFresh;return std::pair{Decisions::RootDecision(scope,root,deniedRoot),Decisions::FreshDecision(scope,root,deniedFresh)};});const bool immediate=work.wait_for(1s)==std::future_status::ready;q.unlock();const auto denied=work.get();Check(immediate&&denied.first==ScopeResult::Busy&&denied.second==ScopeResult::Busy,"candidate actual Q contention inserts no lifecycle owner");}
