/** @summary Preserve exact lifecycle denial taxonomy across candidate and previously active retirement. */
void LifecycleDenials(){
    // @summary Every row owns a real separately issued scope/grant; no activation is forced for candidate rows.
    for(unsigned mode=0;mode!=7;++mode){auto domain=std::make_shared<RuntimeCommitDomain>();std::shared_ptr<RuntimeScope> scope=RuntimeScopeTestAccess::Create(domain);scope->SetReadiness(true);if(mode==6)Check(scope->CommitActivation(),"active retirement row genuinely activated");const auto root=RuntimeScopeTestAccess::Issue(*scope,false,true,true,1,mode==3?50ms:std::chrono::minutes(1));Check(root.owner!=0,"denial row original grant issued");auto supplied=root;ScopeResult expected=ScopeResult::Denied;
        std::shared_ptr<RuntimeScope> target=scope;
        if(mode==0){target=RuntimeScopeTestAccess::Create();target->SetReadiness(true);expected=ScopeResult::Stale;}
        else if(mode==1){++supplied.reservation;}
        else if(mode==2){Check(RuntimeScopeTestAccess::Revoke(*scope,root.grantGeneration)==ScopeResult::Ok,"actual original grant revoked");}
        else if(mode==3){std::this_thread::sleep_until(root.deadline);}
        else if(mode==4){scope->SetReadiness(false);expected=ScopeResult::NotReady;}
        else if(mode==5){domain->RequestStop();}
        else{static_cast<void>(Scope::DrainOne(*scope));Check(scope->Current().activationCommitted&&scope->Current().stopping,"retired active scope never reverts to candidate");}
        const auto before=Scope::Observe(*target);LifecycleDecision rootView,fresh;const auto rootResult=Decisions::RootDecision(target,supplied,rootView);const auto freshResult=Decisions::FreshDecision(target,supplied,fresh);const auto after=Scope::Observe(*target);
        std::cerr<<"lifecycle denial mode="<<mode<<" rootResult="<<static_cast<int>(rootResult)<<" freshResult="<<static_cast<int>(freshResult)<<" expected="<<static_cast<int>(expected)<<std::endl;
        Check(rootResult==expected&&freshResult==expected&&rootView.Context().owner==0&&fresh.Context().owner==0,"lifecycle exact original authority denial retained");Check(after.commandTickets==before.commandTickets&&after.rootReservations==before.rootReservations&&after.nonCommandFreshReservations==before.nonCommandFreshReservations,"denied lifecycle factories insert no reservation or ticket");
    }
    auto domain=std::make_shared<RuntimeCommitDomain>();std::shared_ptr<RuntimeScope> scope=RuntimeScopeTestAccess::Create(domain);scope->SetReadiness(true);const auto root=RuntimeScopeTestAccess::Issue(*scope);Check(root.owner!=0,"stop-before-activation root issued");static_cast<void>(Scope::DrainOne(*scope));Check(!scope->Current().activationCommitted&&scope->Current().stopping,"candidate stopped before activation remains closed");LifecycleDecision view,fresh;Check(Decisions::RootDecision(scope,root,view)==ScopeResult::Denied,"stopped candidate root denied");Check(Decisions::FreshDecision(scope,root,fresh)==ScopeResult::Denied,"stopped candidate fresh denied");Check(Scope::Observe(*scope).commandTickets==0&&Scope::Observe(*scope).rootReservations==1,"stopped candidate root bookkeeping preserved");
}
